function [ys_, params, info] = steadystate(ys_, exo_, params)
% Steady state generated by Dynare preprocessor
    info = 0;
    ys_(32)=0;
    ys_(33)=0;
    ys_(34)=0;
    ys_(35)=0;
    ys_(22)=ys_(32)+(1-params(6))*(ys_(34)-log(1-params(6)));
    ys_(23)=ys_(33)+(1-params(7))*(ys_(35)-log(1-params(7)));
    ys_(24)=0;
    ys_(25)=0;
    ys_(28)=0;
    ys_(29)=0;
    ys_(30)=0;
    ys_(31)=0;
    ys_(26)=0;
    ys_(27)=0;
    k_v_ratio1=params(6)*params(1)/(1-params(1)*(1-params(8)));
    k_v_ratio2=params(7)*params(1)/(1-params(1)*(1-params(9)));
    ys_(6)=(ys_(22)+params(6)*log(k_v_ratio1)-params(6)*log(params(6)))/(1-params(6));
    ys_(7)=(ys_(23)+params(7)*log(k_v_ratio2)-params(7)*log(params(7)))/(1-params(7));
    ys_(14)=log(k_v_ratio1)+ys_(6);
    ys_(15)=log(k_v_ratio2)+ys_(7);
    ys_(4)=ys_(6)-log(params(4));
    ys_(5)=ys_(7)-log(params(5));
    ys_(8)=ys_(4)+log(1-params(4));
    ys_(9)=ys_(5)+log(1-params(5));
    ys_(16)=ys_(14)+log(params(8));
    ys_(17)=ys_(15)+log(params(9));
    ys_(10)=ys_(8)+log(params(10));
    ys_(12)=ys_(8)+log(params(11));
    ys_(11)=ys_(9)+log(params(12));
    ys_(13)=ys_(9)+log(params(13));
    ys_(18)=ys_(16)+log(params(14));
    ys_(20)=ys_(16)+log(params(15));
    ys_(19)=ys_(17)+log(params(16));
    ys_(21)=ys_(17)+log(params(17));
    ys_(2)=log(exp(ys_(4))-exp(ys_(10))-exp(ys_(11))-exp(ys_(18))-exp(ys_(19)));
    ys_(3)=log(exp(ys_(5))-exp(ys_(12))-exp(ys_(13))-exp(ys_(20))-exp(ys_(21)));
    ys_(1)=params(2)*(ys_(2)-log(params(2)))+params(3)*(ys_(3)-log(params(3)));
    % Auxiliary equations
end
